//! Post-output shaping of the stdout document.
//!
//! Two things the spec asks for that the render pass alone does not give:
//!
//! * an empty workspace's `list` prints *nothing at all*, but `App::run` writes
//!   a handled command's text with `writeln!`, so an empty render would still
//!   leave a bare newline on stdout;
//! * the machine document is one line, while `standout-render` serializes JSON
//!   with `serde_json::to_string_pretty` (`docs/crates/render/topics/templating.md`,
//!   "Structured Output").
//!
//! Both are presentation concerns, so they sit in a post-output hook rather
//! than in a handler.

use clap::ArgMatches;
use standout_dispatch::{CommandContext, HookError, RenderedOutput};

pub fn shape_document(
    _matches: &ArgMatches,
    _ctx: &CommandContext,
    output: RenderedOutput,
) -> Result<RenderedOutput, HookError> {
    let RenderedOutput::Text(text) = &output else {
        return Ok(output);
    };

    let rendered = text.to_string();
    if rendered.is_empty() {
        return Ok(RenderedOutput::Silent);
    }

    Ok(RenderedOutput::Text(compact_json(rendered).into()))
}

/// Collapse a pretty-printed JSON object onto one line. Text, YAML, XML and CSV
/// renderings are left alone: none of them parse as a JSON object.
fn compact_json(rendered: String) -> String {
    let Ok(value) = serde_json::from_str::<serde_json::Value>(&rendered) else {
        return rendered;
    };
    if !value.is_object() {
        return rendered;
