/// Collapse a pretty-printed JSON object onto one line. Text, YAML, XML and CSV
/// renderings are left alone: none of them parse as a JSON object.
///
/// The whitespace is dropped in place rather than by re-serializing a
/// `serde_json::Value`, because a `Value` is a sorted map by default and the
/// document's key order is the handler's field order, not the alphabet's.
fn compact_json(rendered: String) -> String {
    let Ok(value) = serde_json::from_str::<serde_json::Value>(&rendered) else {
        return rendered;
    };
    if !value.is_object() {
        return rendered;
    }
    strip_insignificant_whitespace(&rendered)
}

/// Drop every byte of whitespace that sits outside a string literal. The input
/// is known-valid JSON, so the result is the compact spelling of the same
/// document, key order intact.
fn strip_insignificant_whitespace(json: &str) -> String {
    let mut out = String::with_capacity(json.len());
    let mut in_string = false;
    let mut escaped = false;

    for character in json.chars() {
        if in_string {
            out.push(character);
            if escaped {
                escaped = false;
            } else if character == '\\' {
                escaped = true;
            } else if character == '"' {
                in_string = false;
            }
            continue;
        }
        if character == '"' {
            in_string = true;
            out.push(character);
        } else if !character.is_whitespace() {
            out.push(character);
        }
    }

    out
}

