//! Post-output shaping of the stdout document.
//!
//! Two things the spec asks for that the render pass alone does not give:
//!
//! * an empty workspace's `list` prints *nothing at all*, but `App::run` writes
//!   a handled command's text with `writeln!`, so an empty render would still
//!   leave a bare newline on stdout;
//! * the machine document is one line, while `standout-render` serializes JSON
//!   with `serde_json::to_string_pretty` (`docs/crates/render/topics/templating.md`,
//!   "Structured Output").
//!
//! Both are presentation concerns, so they sit in a post-output hook rather
//! than in a handler.

use clap::ArgMatches;
use standout_dispatch::{CommandContext, HookError, RenderedOutput};

pub fn shape_document(
    _matches: &ArgMatches,
    _ctx: &CommandContext,
    output: RenderedOutput,
) -> Result<RenderedOutput, HookError> {
    let RenderedOutput::Text(mut text) = output else {
        return Ok(output);
    };

    if text.formatted.is_empty() {
        return Ok(RenderedOutput::Silent);
    }

    text.formatted = compact_json(text.formatted);
    text.raw = compact_json(text.raw);
    Ok(RenderedOutput::Text(text))
}

/// Collapse a pretty-printed JSON object onto one line. Text, YAML, XML and CSV
/// renderings are left alone: none of them parse as a JSON object.
///
/// The whitespace is dropped in place rather than by re-serializing a
/// `serde_json::Value`, because a `Value` is a sorted map by default and the
/// document's key order is the handler's field order, not the alphabet's.
fn compact_json(rendered: String) -> String {
    let Ok(value) = serde_json::from_str::<serde_json::Value>(&rendered) else {
        return rendered;
    };
    if !value.is_object() {
        return rendered;
    }
    strip_insignificant_whitespace(&rendered)
}

/// Drop every byte of whitespace that sits outside a string literal. The input
/// is known-valid JSON, so the result is the compact spelling of the same
/// document, key order intact.
fn strip_insignificant_whitespace(json: &str) -> String {
    let mut out = String::with_capacity(json.len());
    let mut in_string = false;
    let mut escaped = false;

    for character in json.chars() {
        if in_string {
            out.push(character);
            if escaped {
                escaped = false;
            } else if character == '\\' {
                escaped = true;
            } else if character == '"' {
                in_string = false;
            }
            continue;
        }
        if character == '"' {
            in_string = true;
            out.push(character);
        } else if !character.is_whitespace() {
            out.push(character);
        }
    }

    out
}

#[cfg(test)]
mod tests {
    use super::compact_json;

    #[test]
    fn a_json_object_is_collapsed_onto_one_line() {
        let pretty = "{\n  \"packages\": [\n    {\n      \"name\": \"alpha\",\n      \"version\": \"1.0.0\"\n    }\n  ]\n}";
        assert_eq!(
            compact_json(pretty.to_string()),
            r#"{"packages":[{"name":"alpha","version":"1.0.0"}]}"#
        );
    }

    #[test]
    fn key_order_and_string_contents_survive() {
        let pretty = "{\n  \"installed\": [\n    {\n      \"name\": \"a b\",\n      \"version\": \"1.0\"\n    }\n  ],\n  \"count\": 1\n}";
        assert_eq!(
            compact_json(pretty.to_string()),
            r#"{"installed":[{"name":"a b","version":"1.0"}],"count":1}"#
        );
    }

    #[test]
    fn an_escaped_quote_does_not_end_a_string() {
        let pretty = "{\n  \"name\": \"a\\\" b\"\n}";
        assert_eq!(compact_json(pretty.to_string()), "{\"name\":\"a\\\" b\"}");
    }

    #[test]
    fn other_renderings_pass_through() {
        assert_eq!(compact_json("alpha 1.0.0".into()), "alpha 1.0.0");
        assert_eq!(
            compact_json("2 packages installed.".into()),
            "2 packages installed."
        );
        assert_eq!(
            compact_json("packages:\n- name: alpha\n".into()),
            "packages:\n- name: alpha\n"
        );
    }
}

//! `pnpmlike` — a workspace script runner that speaks on three channels:
//! data on stdout, progress on stderr through a reporter, and logs on stderr
//! through a level.

mod channels;
mod cli;
mod handlers;
mod hooks;
mod manifest;
mod session;
mod views;

use clap::CommandFactory;
use standout::cli::{App, Dispatch};
use standout::EmbeddedTemplates;
use standout_dispatch::Hooks;

use crate::cli::Cli;
use crate::session::Invocation;

/// The commands, bound to the handlers of the same name.
///
/// `run` hands the terminal to a child process and has nothing for a template
/// to render, so it is marked `silent`.
#[derive(Dispatch)]
#[dispatch(handlers = handlers)]
pub enum Commands {
    #[dispatch(pure)]
    List,
    #[dispatch(pure)]
    Install,
    #[dispatch(pure, silent)]
    Run,
}

/// Templates are inline rather than embedded from files: the bytes on stdout
/// are part of the contract, and a template file's trailing newline is not
/// something to leave to an editor. MiniJinja consumes one final newline and
/// `App::run` appends one, so neither template ends with one.
const TEMPLATES: &[(&str, &str)] = &[
    (
        "list",
        "{% for package in packages %}{{ package.name }} {{ package.version }}\
         {% if not loop.last %}\n{% endif %}{% endfor %}",
    ),
    ("install", "{{ count }} packages installed."),
];

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let argv: Vec<String> = std::env::args().collect();

    let app = App::builder()
        .app_state(Invocation::from_argv(&argv))
        .templates(EmbeddedTemplates::new(TEMPLATES, ""))
        .commands(Commands::dispatch_config())?
        .hooks("list", Hooks::new().post_output(hooks::shape_document))
        .hooks("install", Hooks::new().post_output(hooks::shape_document))
        .build()?;

    app.run(Cli::command(), argv);
    Ok(())
}

